// Turns captured PNGs into the WebP files the docs site serves, and writes the
// small generated file that tells the docs site which images exist, what
// address to show in the browser frame, and which images are close-ups.

import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import sharp from "sharp";
import {
  DEVICE_SCALE_FACTOR,
  IMAGES_DIR,
  MANIFEST_FILE,
  PLACEHOLDER_HOST,
  WEBP_QUALITY,
} from "./constants";
import { WORK_DIR } from "./environment";
import type { ManualShot, Shot, Theme } from "./types";

export function imagePath(name: string, theme: Theme): string {
  return path.join(
    IMAGES_DIR,
    theme === "dark" ? `${name}.dark.webp` : `${name}.webp`
  );
}

export async function writeImage(
  name: string,
  theme: Theme,
  png: Buffer
): Promise<number> {
  mkdirSync(IMAGES_DIR, { recursive: true });
  const info = await sharp(png)
    .webp({ quality: WEBP_QUALITY, effort: 6, smartSubsample: true })
    .toFile(imagePath(name, theme));
  return info.size;
}

function identifier(name: string, theme: Theme): string {
  const camel = name.replace(/-(\w)/g, (_, c: string) => c.toUpperCase());
  return `${camel}${theme === "dark" ? "Dark" : "Light"}`;
}

export interface ResolvedShot {
  address: string;
  shot: Shot;
}

// Only lists shots whose light and dark files both exist, so the docs site
// never imports a file that is missing.
export function writeManifest(resolved: readonly ResolvedShot[]): void {
  const present = resolved.filter(
    ({ shot }) =>
      existsSync(imagePath(shot.name, "light")) &&
      existsSync(imagePath(shot.name, "dark"))
  );

  const imports = present.flatMap(({ shot }) =>
    (["light", "dark"] as const).map(
      (theme) =>
        `import ${identifier(shot.name, theme)} from "../../public/images/${path.basename(imagePath(shot.name, theme))}";`
    )
  );
  const entries = present.map(({ shot, address }) => {
    const kind = shot.closeup ? "closeup" : "window";
    return `  "${shot.name}": {\n    address: ${JSON.stringify(address)},\n    dark: ${identifier(shot.name, "dark")},\n    kind: "${kind}",\n    light: ${identifier(shot.name, "light")},\n  },`;
  });

  const source = `// Generated by \`npm run docs:screenshots\` in \`web/\`. Do not edit by hand.
import type { StaticImageData } from "next/image";
${imports.join("\n")}

/** Pixels in the image for each CSS pixel on screen. */
export const SCREENSHOT_SCALE = ${DEVICE_SCALE_FACTOR};

export interface Screenshot {
  /** Shown in the browser frame, on a placeholder host. */
  address: string;
  dark: StaticImageData;
  /** Close-ups have no browser frame. */
  kind: "closeup" | "window";
  light: StaticImageData;
}

export const screenshots: Record<string, Screenshot> = {
${entries.join("\n")}
};
`;
  writeFileSync(MANIFEST_FILE, source);
}

export function displayAddress(
  pathAndQuery: string,
  override?: string
): string {
  const pathname = override ?? pathAndQuery;
  return `${PLACEHOLDER_HOST}${pathname === "/" ? "" : pathname}`;
}

function ageInDays(date: string): number {
  return Math.floor((Date.now() - new Date(date).getTime()) / 86_400_000);
}

export interface RunReport {
  failures: { error: string; name: string }[];
  manual: readonly ManualShot[];
  taken: string[];
  /** Problems that did not stop a screenshot, such as a failed cleanup. */
  warnings: { error: string; name: string }[];
}

export function writeSummary(report: RunReport): string {
  const lines: string[] = [];
  lines.push(
    "Automated refresh of the docs screenshots. Each image is a light and a dark WebP file in `docs/site/public/images/`.",
    ""
  );
  lines.push(`Retaken: ${report.taken.length}`, "");
  if (report.failures.length > 0) {
    lines.push(
      "## Screens that failed",
      "",
      "These keep their previous images. Fix the steps in `web/scripts/docs-screenshots/shots.ts`, then retake them with `make docs-screenshots ONLY=<name>`.",
      ""
    );
    for (const failure of report.failures) {
      lines.push(`- \`${failure.name}\`: ${failure.error.split("\n")[0]}`);
    }
    lines.push("");
  }
  if (report.warnings.length > 0) {
    lines.push("## Warnings", "");
    for (const warning of report.warnings) {
      lines.push(`- \`${warning.name}\`: ${warning.error.split("\n")[0]}`);
    }
    lines.push("");
  }
  if (report.manual.length > 0) {
    lines.push(
      "## Screenshots taken by hand",
      "",
      "The script cannot capture these.",
      ""
    );
    for (const shot of report.manual) {
      lines.push(
        `- \`${shot.name}\`, last taken ${shot.lastTaken} (${ageInDays(shot.lastTaken)} days ago). ${shot.note}`
      );
    }
    lines.push("");
  }
  const text = lines.join("\n");
  mkdirSync(WORK_DIR, { recursive: true });
  writeFileSync(path.join(WORK_DIR, "summary.md"), text);
  return text;
}
